namespace CheckoutPricing.Domain;

public static class CheckoutDiscountPolicy
{
    private const int LoyaltyMinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int DiscountCents(int subtotalCents, LoyaltyTier loyaltyTier, string? promoCode)
    {
        var loyaltyCents = LoyaltyCents(subtotalCents, loyaltyTier);
        var promoCents = PromoCents(subtotalCents - loyaltyCents, promoCode);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }

    private static int LoyaltyCents(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents < LoyaltyMinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyDiscountPolicy.DiscountCents(subtotalCents, loyaltyTier), LoyaltyCapCents);

    private static int PromoCents(int remainingCents, string? promoCode)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return Welcome5Cents;
        }

        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(remainingCents / 10, Summer10CapCents);
        }

        return 0;
    }
}

